    if (-not (Test-Path $carpeta)) { New-Item -ItemType Directory -Path $carpeta -Force | Out-Null }
    [IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String(($a.b64 -replace '\s','')))
    Write-Host ("  OK  " + $a.ruta) -ForegroundColor Green
}
Write-Host ""
$pyExe = $null; $pyArgs = @()
foreach ($c in @(@{ exe = "py"; args = @("-3") }, @{ exe = "python"; args = @() })) {
    if (-not (Get-Command $c.exe -ErrorAction SilentlyContinue)) { continue }
    $v = & $c.exe @($c.args) --version 2>&1 | Out-String
    if ($v -match "Python (\d+)\.(\d+)" -and [int]$Matches[1] -eq 3 -and [int]$Matches[2] -ge 11) {
        $pyExe = $c.exe; $pyArgs = $c.args; break
    }
}
if ($pyExe) {
    $antes = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    & $pyExe @pyArgs -m pytest tests/ -q 2>&1 | Select-Object -Last 4 | Out-Host
    $ErrorActionPreference = $antes
}
